namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
    public DateTime SubmittedAt { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, quantity, structure, space, and change." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events, civilizations, and historical analysis." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Associate Professor", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 40 papers in top-tier conferences and holds a PhD from MIT.", Email = "achen@university.edu", DepartmentId = 1 },
            new() { Id = 2, Name = "Dr. Robert Kim", Title = "Professor", Bio = "Dr. Kim is an expert in distributed systems and cloud computing with 20 years of teaching experience.", Email = "rkim@university.edu", DepartmentId = 1 },
            new() { Id = 3, Name = "Dr. Sarah Patel", Title = "Professor", Bio = "Dr. Patel is a number theorist whose research focuses on algebraic geometry. She is a recipient of the National Science Foundation CAREER Award.", Email = "spatel@university.edu", DepartmentId = 2 },
            new() { Id = 4, Name = "Dr. James Liu", Title = "Assistant Professor", Bio = "Dr. Liu specializes in applied mathematics and mathematical modeling with applications in biology and ecology.", Email = "jliu@university.edu", DepartmentId = 2 },
            new() { Id = 5, Name = "Dr. Maria Gonzalez", Title = "Professor", Bio = "Dr. Gonzalez is an experimental physicist specializing in quantum optics and photonics. She directs the university's Quantum Lab.", Email = "mgonzalez@university.edu", DepartmentId = 3 },
            new() { Id = 6, Name = "Dr. David Park", Title = "Associate Professor", Bio = "Dr. Park studies condensed matter physics and has contributed to breakthroughs in superconductor research.", Email = "dpark@university.edu", DepartmentId = 3 },
            new() { Id = 7, Name = "Dr. Emily Watson", Title = "Professor", Bio = "Dr. Watson is a literary scholar specializing in 19th-century American literature. She has authored three books on the works of Emily Dickinson.", Email = "ewatson@university.edu", DepartmentId = 4 },
            new() { Id = 8, Name = "Dr. Michael Torres", Title = "Associate Professor", Bio = "Dr. Torres focuses on creative writing and modern poetry. He is an award-winning poet and essayist.", Email = "mtorres@university.edu", DepartmentId = 4 },
            new() { Id = 9, Name = "Dr. Linda Nguyen", Title = "Professor", Bio = "Dr. Nguyen is a historian specializing in East Asian history and transnational studies. She has received multiple teaching excellence awards.", Email = "lnguyen@university.edu", DepartmentId = 5 },
            new() { Id = 10, Name = "Dr. Thomas Brown", Title = "Associate Professor", Bio = "Dr. Brown studies the American Civil War era and Reconstruction. He curates the university's historical archives.", Email = "tbrown@university.edu", DepartmentId = 5 }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Computer Science", Code = "CS 101", Description = "A broad introduction to computer science covering programming fundamentals, algorithms, data structures, and computational thinking. No prior experience required.", Credits = 3, Schedule = "MWF 10:00-10:50 AM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and hash tables. Analysis of algorithm efficiency and sorting techniques.", Credits = 4, Schedule = "TTh 1:00-2:15 PM", DepartmentId = 1, InstructorId = 2, IsFeatured = false },
            new() { Id = 3, Title = "Artificial Intelligence", Code = "CS 380", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning, natural language processing, and neural networks.", Credits = 3, Schedule = "MWF 2:00-2:50 PM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 4, Title = "Database Systems", Code = "CS 340", Description = "Relational database design, SQL, normalization, transaction management, and introduction to NoSQL databases.", Credits = 3, Schedule = "TTh 9:30-10:45 AM", DepartmentId = 1, InstructorId = 2, IsFeatured = false },

            // Mathematics
            new() { Id = 5, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "MWF 9:00-9:50 AM", DepartmentId = 2, InstructorId = 3, IsFeatured = true },
            new() { Id = 6, Title = "Linear Algebra", Code = "MATH 220", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications. Essential for advanced studies in science and engineering.", Credits = 3, Schedule = "TTh 11:00-12:15 PM", DepartmentId = 2, InstructorId = 4, IsFeatured = false },
            new() { Id = 7, Title = "Probability and Statistics", Code = "MATH 360", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 1:00-1:50 PM", DepartmentId = 2, InstructorId = 3, IsFeatured = false },

            // Physics
            new() { Id = 8, Title = "General Physics I", Code = "PHYS 201", Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with weekly laboratory sessions.", Credits = 4, Schedule = "MWF 11:00-11:50 AM", DepartmentId = 3, InstructorId = 5, IsFeatured = true },
            new() { Id = 9, Title = "Electromagnetism", Code = "PHYS 301", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 3, Schedule = "TTh 2:30-3:45 PM", DepartmentId = 3, InstructorId = 6, IsFeatured = false },
            new() { Id = 10, Title = "Quantum Mechanics", Code = "PHYS 420", Description = "Wave-particle duality, Schrödinger equation, quantum states, and applications in modern physics.", Credits = 3, Schedule = "MWF 3:00-3:50 PM", DepartmentId = 3, InstructorId = 5, IsFeatured = false },

            // English
            new() { Id = 11, Title = "English Composition", Code = "ENG 101", Description = "Develop critical reading and writing skills through expository and argumentative essays. Focus on clarity, organization, and research methods.", Credits = 3, Schedule = "MWF 10:00-10:50 AM", DepartmentId = 4, InstructorId = 7, IsFeatured = false },
            new() { Id = 12, Title = "American Literature", Code = "ENG 250", Description = "Survey of American literature from colonial times to the present, including works by Hawthorne, Twain, Fitzgerald, and Morrison.", Credits = 3, Schedule = "TTh 1:00-2:15 PM", DepartmentId = 4, InstructorId = 7, IsFeatured = false },
            new() { Id = 13, Title = "Creative Writing Workshop", Code = "ENG 310", Description = "Workshop-based course in fiction and poetry writing. Students produce and critique original works in a collaborative setting.", Credits = 3, Schedule = "W 6:00-8:30 PM", DepartmentId = 4, InstructorId = 8, IsFeatured = true },

            // History
            new() { Id = 14, Title = "World History to 1500", Code = "HIST 101", Description = "Survey of major civilizations, cultures, and events from ancient times through the late medieval period.", Credits = 3, Schedule = "MWF 9:00-9:50 AM", DepartmentId = 5, InstructorId = 9, IsFeatured = false },
            new() { Id = 15, Title = "Modern East Asian History", Code = "HIST 340", Description = "Political, economic, and cultural developments in China, Japan, and Korea from the 19th century to the present.", Credits = 3, Schedule = "TTh 11:00-12:15 PM", DepartmentId = 5, InstructorId = 9, IsFeatured = false },
            new() { Id = 16, Title = "The American Civil War", Code = "HIST 355", Description = "In-depth study of the causes, conduct, and consequences of the American Civil War and Reconstruction era.", Credits = 3, Schedule = "TTh 3:30-4:45 PM", DepartmentId = 5, InstructorId = 10, IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

