@page "/courses"
@inject CatalogService CatalogService

<PageTitle>Browse Courses</PageTitle>

<h1 class="mb-4">Browse Courses</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or description..." />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead class="table-dark">
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th>Department</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                var dept = CatalogService.GetDepartment(course.DepartmentId);
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td><span class="badge bg-primary">@course.Credits</span></td>
                    <td>@course.Schedule</td>
                    <td>@dept?.Name</td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/enroll"
@inject CatalogService CatalogService

<PageTitle>Enroll</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title)</strong> has been received.</p>
        <hr />
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    @if (_validationErrors.Count > 0)
    {
        <div class="alert alert-danger">
            <ul class="mb-0">
                @foreach (var error in _validationErrors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    <div class="row">
        <div class="col-md-8 col-lg-6">
            <form method="post">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Student Name</label>
                    <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select id="courseId" name="Model.CourseId" class="form-select" required>
                        <option value="0">-- Select a Course --</option>
                        @foreach (var course in CatalogService.GetCourses(null, null))
                        {
                            <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code - @course.Title</option>
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool _submitted;
    private List<string> _validationErrors = new();

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpContextAccessor is not null)
            return;
    }

    [CascadingParameter]
    public HttpContext? HttpContext { get; set; }

    protected override void OnAfterRender(bool firstRender) { }

    public void OnPost()
    {
        _validationErrors.Clear();

        if (string.IsNullOrWhiteSpace(Model.StudentName))
            _validationErrors.Add("Student Name is required.");
        if (string.IsNullOrWhiteSpace(Model.StudentId))
            _validationErrors.Add("Student ID is required.");
        if (Model.CourseId == 0)
            _validationErrors.Add("Please select a course.");

        if (_validationErrors.Count == 0)
        {
            Model.SubmittedAt = DateTime.Now;
            CatalogService.SubmitEnrollmentRequest(Model);
            _submitted = true;
        }
    }
}

