 @page "/enroll"
 @using Microsoft.AspNetCore.Http
 @inject CatalogService CatalogService

 <PageTitle>Enroll</PageTitle>

 <h1 class="mb-4">Enrollment Request</h1>

 @if (_submitted)
 {
     <div class="alert alert-success">
         <h4 class="alert-heading">Enrollment Request Submitted!</h4>
         <p>Thank you, <strong>@Model!.StudentName</strong>. Your enrollment request for <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title)</strong> has been received.</p>
         <hr />
         <a href="/courses" class="btn btn-primary">Browse More Courses</a>
     </div>
 }
 else
 {
     @if (_validationErrors.Count > 0)
     {
         <div class="alert alert-danger">
             <ul class="mb-0">
                 @foreach (var error in _validationErrors)
                 {
                     <li>@error</li>
                 }
             </ul>
         </div>
     }

     <div class="row">
         <div class="col-md-8 col-lg-6">
             <form method="post">
                 <AntiforgeryToken />

                 <div class="mb-3">
                     <label for="studentName" class="form-label">Student Name</label>
                     <input type="text" id="studentName" name="Model.StudentName" value="@Model!.StudentName" class="form-control" required />
                 </div>

                 <div class="mb-3">
                     <label for="studentId" class="form-label">Student ID</label>
                     <input type="text" id="studentId" name="Model.StudentId" value="@Model!.StudentId" class="form-control" required />
                 </div>

                 <div class="mb-3">
                     <label for="courseId" class="form-label">Course</label>
                     <select id="courseId" name="Model.CourseId" class="form-select" required>
                         <option value="0">-- Select a Course --</option>
                         @foreach (var course in CatalogService.GetCourses(null, null))
                         {
                             <option value="@course.Id" selected="@(Model!.CourseId == course.Id)">@course.Code - @course.Title</option>
                         }
                     </select>
                 </div>

                 <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                 <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
             </form>
         </div>
     </div>
 }

 @code {
     [SupplyParameterFromForm]
     public EnrollmentRequest? Model { get; set; }

     [SupplyParameterFromQuery]
     public int? CourseId { get; set; }

     private bool _submitted;
     private List<string> _validationErrors = new();

     protected override void OnInitialized()
     {
         Model ??= new();
         if (CourseId.HasValue && Model.CourseId == 0)
         {
             Model.CourseId = CourseId.Value;
         }

         if (HttpContext is not null && HttpMethods.IsPost(HttpContext.Request.Method))
         {
             OnPost();
         }
     }

     [CascadingParameter]
     public HttpContext? HttpContext { get; set; }

     private void OnPost()
     {
         _validationErrors.Clear();

         if (string.IsNullOrWhiteSpace(Model!.StudentName))
             _validationErrors.Add("Student Name is required.");
